namespace emon;


public static class Bytestest {
    [Xunit.Fact]
    public static void TestSignedReadsTakeTheHighBitAsASign() {
        emon.Testport.AssertEq(Bytes.ByI8(emon.Testport.HexBlob("7f 80 ff"), 0), 127, "0x7f");
        emon.Testport.AssertEq(Bytes.ByI8(emon.Testport.HexBlob("7f 80 ff"), 1), -128, "0x80");
        emon.Testport.AssertEq(Bytes.ByI8(emon.Testport.HexBlob("7f 80 ff"), 2), -1, "0xff");
        emon.Testport.AssertEq(Bytes.ByI16(emon.Testport.HexBlob("7f ff 80 00 ff fe"), 0), 32767, "be 7fff");
        emon.Testport.AssertEq(Bytes.ByI16(emon.Testport.HexBlob("7f ff 80 00 ff fe"), 2), -32768, "be 8000");
        emon.Testport.AssertEq(Bytes.ByI16(emon.Testport.HexBlob("7f ff 80 00 ff fe"), 4), -2, "be fffe");
        emon.Testport.AssertEq(Bytes.ByI16le(emon.Testport.HexBlob("ff 7f 00 80 fe ff"), 0), 32767, "le 7fff");
        emon.Testport.AssertEq(Bytes.ByI16le(emon.Testport.HexBlob("ff 7f 00 80 fe ff"), 2), -32768, "le 8000");
        emon.Testport.AssertEq(Bytes.ByI16le(emon.Testport.HexBlob("ff 7f 00 80 fe ff"), 4), -2, "le fffe");
    }
    [Xunit.Fact]
    public static void Test24BitReadsAreUnsignedInBothOrders() {
        emon.Testport.AssertEq(Bytes.ByU24(emon.Testport.HexBlob("01 02 03 ff ff ff"), 0), 66051, "be 010203");
        emon.Testport.AssertEq(Bytes.ByU24(emon.Testport.HexBlob("01 02 03 ff ff ff"), 3), 16777215, "be ffffff");
        emon.Testport.AssertEq(Bytes.ByU24le(emon.Testport.HexBlob("03 02 01 ff ff ff"), 0), 66051, "le 010203");
        emon.Testport.AssertEq(Bytes.ByU24le(emon.Testport.HexBlob("03 02 01 ff ff ff"), 3), 16777215, "le ffffff");
    }
    [Xunit.Fact]
    public static void TestUnsigned32BitWidensWithoutGoingNegative() {
        emon.Testport.AssertEq64(Bytes.ByU3264(emon.Testport.HexBlob("ff ff ff ff"), 0), 4294967295, "be ffffffff");
        emon.Testport.AssertEq64(Bytes.ByU3264(emon.Testport.HexBlob("80 00 00 00"), 0), 2147483648, "be 80000000");
        emon.Testport.AssertEq64(Bytes.ByU3264(emon.Testport.HexBlob("00 00 01 00"), 0), 256, "be 00000100");
        emon.Testport.AssertEq64(Bytes.ByU32le64(emon.Testport.HexBlob("ff ff ff ff"), 0), 4294967295, "le ffffffff");
        emon.Testport.AssertEq64(Bytes.ByU32le64(emon.Testport.HexBlob("00 00 00 80"), 0), 2147483648, "le 80000000");
        emon.Testport.AssertEq64(Bytes.ByU32le64(emon.Testport.HexBlob("00 01 00 00"), 0), 256, "le 00000100");
    }
    [Xunit.Fact]
    public static void TestBoundsQuestionsDoNotReadOutOfRange() {
        emon.Testport.AssertEq(Bytes.ByIn(emon.Testport.HexBlob("00 01 02"), 0, 3), 1, "the whole blob");
        emon.Testport.AssertEq(Bytes.ByIn(emon.Testport.HexBlob("00 01 02"), 1, 3), 0, "one past the end");
        emon.Testport.AssertEq(Bytes.ByIn(emon.Testport.HexBlob("00 01 02"), 3, 0), 1, "an empty read at the end");
        emon.Testport.AssertEq(Bytes.ByIn(emon.Testport.HexBlob("00 01 02"), 4, 0), 0, "an empty read past the end");
        emon.Testport.AssertEq(Bytes.ByIn(emon.Testport.HexBlob("00 01 02"), -1, 1), 0, "a negative index");
        emon.Testport.AssertEq(Bytes.ByIn(emon.Testport.HexBlob("00 01 02"), 1, -1), 0, "a negative count");
        emon.Testport.AssertEq(Bytes.ByIn(emon.Testport.HexBlob("00 01 02"), 1, 2147483647), 0, "a count that would wrap i + n");
    }
    [Xunit.Fact]
    public static void TestReadsWithADefaultAnswerItOffTheEnd() {
        emon.Testport.AssertEq(Bytes.ByU8Or(emon.Testport.HexBlob("0a"), 0, -1), 10, "in range");
        emon.Testport.AssertEq(Bytes.ByU8Or(emon.Testport.HexBlob("0a"), 1, -1), -1, "one past");
        emon.Testport.AssertEq(Bytes.ByU16Or(emon.Testport.HexBlob("01 02"), 0, -1), 258, "u16 in range");
        emon.Testport.AssertEq(Bytes.ByU16Or(emon.Testport.HexBlob("01 02"), 1, -1), -1, "u16 straddling the end");
        emon.Testport.AssertEq(Bytes.ByU32Or(emon.Testport.HexBlob("ff ff ff ff"), 0, 7), -1, "u32 pattern");
        emon.Testport.AssertEq(Bytes.ByU32Or(emon.Testport.HexBlob("ff ff ff"), 0, 7), 7, "u32 short");
    }
    [Xunit.Fact]
    public static void TestSearchingForwardsAndBackwards() {
        emon.Testport.AssertEq(Bytes.ByFind(emon.Testport.TextBlob("abcabcab"), 0, emon.Testport.TextBlob("abc")), 0, "first");
        emon.Testport.AssertEq(Bytes.ByFind(emon.Testport.TextBlob("abcabcab"), 1, emon.Testport.TextBlob("abc")), 3, "from 1");
        emon.Testport.AssertEq(Bytes.ByFind(emon.Testport.TextBlob("abcabcab"), 4, emon.Testport.TextBlob("abc")), -1, "none after 4");
        emon.Testport.AssertEq(Bytes.ByFind(emon.Testport.TextBlob("abcabcab"), -5, emon.Testport.TextBlob("cab")), 2, "negative from is 0");
        emon.Testport.AssertEq(Bytes.ByFind(emon.Testport.TextBlob("abc"), 0, emon.Testport.TextBlob("abcd")), -1, "needle longer than hay");
        emon.Testport.AssertEq(Bytes.ByFind(emon.Testport.TextBlob("abc"), 3, emon.Testport.TextBlob("")), 3, "empty needle at end");
        emon.Testport.AssertEq(Bytes.ByFindBack(emon.Testport.TextBlob("abcabcab"), 100, emon.Testport.TextBlob("abc")), 3, "last");
        emon.Testport.AssertEq(Bytes.ByFindBack(emon.Testport.TextBlob("abcabcab"), 2, emon.Testport.TextBlob("abc")), 0, "last at or before 2");
        emon.Testport.AssertEq(Bytes.ByFindBack(emon.Testport.TextBlob("abcabcab"), 100, emon.Testport.TextBlob("zz")), -1, "absent");
        emon.Testport.AssertEq(Bytes.ByMatchAt(emon.Testport.TextBlob("abcabc"), 3, emon.Testport.TextBlob("abc")), 1, "match at");
        emon.Testport.AssertEq(Bytes.ByMatchAt(emon.Testport.TextBlob("abcabc"), 4, emon.Testport.TextBlob("abc")), 0, "match runs off the end");
    }
